The `$` right below the property `export let asset: ImmichAsset;` indicates that whenever the `asset` change, then run the reactive logic in the `{}` block

No problem, here is a better explaination. The `$: {}` block only run if you include the `reactive property` which is `asset` in this case. Here is how I would do the refactor

```svelte

	export let asset: ImmichAsset;
	$: if (asset.exifInfo) {
		drawMap(asset.exifInfo.latitude, asset.exifInfo.longitude);
	}

	onMount(async () => {
		if (browser) {
			if (asset.exifInfo) {
				await drawMap(asset.exifInfo.latitude, asset.exifInfo.longitude);
			}
		}
	});

	async function drawMap(lat: number, lon: number) {
		if (!leaflet) {
			// @ts-ignore
			leaflet = await import('leaflet');
		}

		if (!map) {
			map = leaflet.map('map');
			leaflet
				.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
					attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
				})
				.addTo(map);
		}

		if (marker) {
			map.removeLayer(marker);
		}

		map.setView([lat || 0, lon || 0], 17);

		marker = leaflet.marker([lat || 0, lon || 0]);
		marker.bindPopup(`${lat || 0},${lon || 0}`);
		map.addLayer(marker);
	}
```


I hope this helps, and let me know if you have any problem.

